CID = 'output'
SEV, ESC, JOIN, FSTR = "print() with several values", "Quotes and escape characters", "Joining and repeating text", "f-strings: the best way to format"
def W(lv, sec, q, starter, sol, e): return dict(lv=lv, ty='code', sec=sec, q=q, starter=starter, sol=sol, e=e)
def F(lv, sec, q, c, fixed, e): return dict(lv=lv, ty='fix', sec=sec, q=q, c=c, fixed=fixed, e=e)
def T(lv, sec, c, e): return dict(lv=lv, ty='type', sec=sec, q="Type exactly what this code prints.", c=c, e=e)
Q = [
 # ---------- Basic ----------
 W(1, SEV, 'Use ONE `print()` with `sep` to print `30-10-2026`. Give it the three numbers 30, 10 and 2026.', '# One print() with sep\n', 'print(30, 10, 2026, sep="-")', "`sep` sets what goes between the values. The default is one space, and `sep=\"-\"` puts a dash there instead."),
 T(1, SEV, 'print("Loading", end="")\nprint("...")\nprint("Done")', "`end=\"\"` stops the first `print()` from starting a new line, so `...` is printed right after `Loading`. The next `print()` ends normally."),
 W(1, ESC, "Print exactly: `It's a holiday`", '# Watch the apostrophe\n', 'print("It\'s a holiday")', "Wrap the text in double quotes, and the apostrophe inside is just a character. (`'It\\'s a holiday'` also works.)"),
 W(1, JOIN, '`first = "Sachin"` and `last = "Tendulkar"`. Use `+` to print the full name with one space in the middle.', 'first = "Sachin"\nlast = "Tendulkar"\n', 'first = "Sachin"\nlast = "Tendulkar"\nprint(first + " " + last)', "`+` glues text together with nothing in between, so add the space yourself: `\" \"`."),
 W(1, JOIN, 'Print a line of 25 `=` signs. Use `*`, do not type them all.', '# Repeat one character\n', 'print("=" * 25)', "Text times a number repeats the text: `\"=\" * 25` gives 25 signs. Great for report lines."),
 F(1, JOIN, "This code should print `Rooms booked: 12`, but it crashes. Fix it.", 'rooms = 12\nprint("Rooms booked: " + rooms)', 'rooms = 12\nprint("Rooms booked: " + str(rooms))', "`+` cannot join text and a number. Turn the number into text with `str()` first (or use an f-string)."),
 W(1, FSTR, '`name = "Kiran"` and `city = "Vizag"`. Use an f-string to print `Kiran lives in Vizag`.', 'name = "Kiran"\ncity = "Vizag"\n', 'name = "Kiran"\ncity = "Vizag"\nprint(f"{name} lives in {city}")', "Put `f` before the quote, then each variable in `{ }`. Python fills in the values."),
 T(1, ESC, r'print("Line 1\nLine 2")', r"`\n` inside text means new line, so the text is printed on two lines."),
 # ---------- Medium ----------
 W(2, FSTR, '`price = 1234.5`. Print `Price: 1234.50` (always 2 decimal places) using an f-string.', 'price = 1234.5\n', 'price = 1234.5\nprint(f"Price: {price:.2f}")', "`:.2f` after the variable means a float with exactly 2 decimal places."),
 W(2, FSTR, '`population = 12345678`. Print `Population: 12,345,678` using an f-string.', 'population = 12345678\n', 'population = 12345678\nprint(f"Population: {population:,}")', "`:,` adds a comma between every group of three digits. It makes big numbers easy to read."),
 T(2, FSTR, 'rate = 0.4567\nprint(f"{rate:.1%}", f"{7:03d}")', "`.1%` multiplies by 100, keeps 1 decimal and adds `%`. `03d` pads a whole number with zeros to 3 digits."),
 F(2, ESC, r"This code should print the file path `C:\new\table.csv`, but the output is broken. Fix it.", r'print("C:\new\table.csv")', r'print(r"C:\new\table.csv")', r"`\n` and `\t` are escape characters (new line and tab). Put `r` before the quote to switch them off, or write each backslash twice: `\\`."),
 F(2, ESC, 'This code should print `She said "Hi" to me`, but it crashes. Fix it.', 'print("She said "Hi" to me")', 'print(\'She said "Hi" to me\')', "The double quote before `Hi` ends the text too early. Wrap the whole text in single quotes, or write `\\\"` for each quote inside."),
 W(2, SEV, 'Use TWO `print()` calls to print `Total: 450` on ONE line. The first prints `Total:` and must not end the line. The second prints the number 450.', '# Two print() calls, one line of output\n', 'print("Total:", end=" ")\nprint(450)', "`end=\" \"` ends the first print with a space instead of a new line, so the second print continues on the same line."),
 T(2, JOIN, 'print("ab" * 3 + "!")\nprint("-" * 5)', "`*` runs first: `\"ab\"` three times is `ababab`, then `+` adds the `!`."),
 F(2, FSTR, "This code should print `Hello Ravi`, but it prints `Hello {name}`. Fix it.", 'name = "Ravi"\nprint("Hello {name}")', 'name = "Ravi"\nprint(f"Hello {name}")', "Without the `f` before the quote, `{name}` is plain text. The `f` switches the slots on."),
 W(2, FSTR, '`qty = 3` and `price = 45`. Use one f-string to print `3 x 45 = 135`. Python must work out the 135.', 'qty = 3\nprice = 45\n', 'qty = 3\nprice = 45\nprint(f"{qty} x {price} = {qty * price}")', "A slot `{ }` can hold maths, not just a name. Python works out `qty * price` and puts the answer in the text."),
 W(2, FSTR, '`items = 4` and `total = 760`. Use the f-string debug trick (a `=` inside the slot) to print `items=4 total=760`.', 'items = 4\ntotal = 760\n', 'items = 4\ntotal = 760\nprint(f"{items=} {total=}")', "`{items=}` prints the name, an `=` and the value. It is a quick way to check variables while you debug."),
 # ---------- Challenge (same chapter, combined) ----------
 W(3, FSTR, '`units = 1250` and `price = 89.9`. Print the revenue as `Revenue: ₹112,375.00` (commas and 2 decimals).', 'units = 1250\nprice = 89.9\n', 'units = 1250\nprice = 89.9\nprint(f"Revenue: ₹{units * price:,.2f}")', "`:,.2f` combines two specs: commas between thousands and exactly 2 decimals. The `₹` is just text before the slot."),
 W(3, FSTR, 'Print this price list, one line per item. Each item name is left-aligned in 15 characters, and each price is right-aligned in 8 characters with 2 decimals.\nItems: Masala Dosa 60, Filter Coffee 25.5, Idli 40.', '# Name: <15, price: >8.2f\n', 'print(f"{\'Masala Dosa\':<15}{60:>8.2f}")\nprint(f"{\'Filter Coffee\':<15}{25.5:>8.2f}")\nprint(f"{\'Idli\':<15}{40:>8.2f}")', "`<15` pads the name with spaces on the right up to 15 characters. `>8.2f` pads the price on the left up to 8 characters, so the decimal points line up."),
 T(3, SEV, 'print("x", "y", sep="--", end="|")\nprint("z")', "`sep=\"--\"` goes between `x` and `y`. `end=\"|\"` replaces the new line, so `z` is printed right after the `|`."),
 F(3, FSTR, "This code should print `Marks: 92.5`, but it prints something strange. Fix it.", 'marks = 92.456\nprint(f"Marks: {marks:.1}")', 'marks = 92.456\nprint(f"Marks: {marks:.1f}")', "Without the `f`, `.1` means 1 significant digit, so Python writes `9e+01`. `.1f` means 1 decimal place."),
 W(3, JOIN, 'Print a banner of three lines: 20 `*` signs, then `MONTHLY REPORT` centred in 20 characters, then 20 `*` signs again.', '# Use * for the lines and ^ to centre\n', 'print("*" * 20)\nprint(f"{\'MONTHLY REPORT\':^20}")\nprint("*" * 20)', "`\"*\" * 20` repeats the star. `^20` centres the title in 20 characters: 3 spaces on each side of the 14 letters."),
 W(3, FSTR, '`invoice_no = 42`, `qty = 3` and `price = 450`. Print `INV-0042 | Qty: 3 | Amount: ₹1,350.00`.', 'invoice_no = 42\nqty = 3\nprice = 450\n', 'invoice_no = 42\nqty = 3\nprice = 450\nprint(f"INV-{invoice_no:04d} | Qty: {qty} | Amount: ₹{qty * price:,.2f}")', "`04d` pads the number with zeros to 4 digits. The amount slot does the maths and then formats it with `:,.2f`."),
 W(3, ESC, r'`item = "Tea"`, `qty = 2` and `rate = 15`. With ONE `print()` and one f-string, print three lines: `Item: Tea`, `Qty: 2` and `Total: ₹30.00`. Use `\n` for the new lines.', 'item = "Tea"\nqty = 2\nrate = 15\n', 'item = "Tea"\nqty = 2\nrate = 15\nprint(f"Item: {item}\\nQty: {qty}\\nTotal: ₹{qty * rate:.2f}")', r"`\n` works inside f-strings too. One `print()` can make a whole multi-line receipt."),
]
